A.kod_metni:
YIGIT:=dayofmonth()><ref(dayofmonth(),-1) ;
ADAM:=valuewhen(1,YIGIT,ref(c,-1)) ;
TX:=valuewhen(1,YIGIT,ref(highestsince(1,YIGIT,h),-1));
RX:=valuewhen(1,YIGIT,ref(lowestsince(1,YIGIT,l),-1));
PVT1:=(ADAM+RX+TX)/3 ;
r1:=2*PVT1-RX ;
s1:=2*PVT1-TX ;
PVT2:=ADAM ;
r2:=PVT2+(TX-RX)/2 ;
s2:=PVT2-(TX-RX)/2 ;
r1;PVT1;s1;
r2;PVT2;s2

